import ThemeContext from './ThemeContext';

const ThemedComponent = () => {
  const { theme, setTheme } = useContext(ThemeContext);

  const toggleTheme = () => {
    setTheme((prevTheme) => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  return (
    <div style={{ background: theme === 'light' ? '#fff' : '#333', color: theme === 'light' ? '#000' : '#fff' }}>
      <p>The current theme is {theme}</p>
      <button onClick={toggleTheme}>Toggle Theme</button>
    </div>
  );
};

export default ThemedComponent;

Using Context.Consumer (Class Components or Functional Components)
import React from 'react';
import ThemeContext from './ThemeContext';

const ThemedComponent = () => (
  <ThemeContext.Consumer>
    {({ theme, setTheme }) => (
      <div style={{ background: theme === 'light' ? '#fff' : '#333', color: theme === 'light' ? '#000' : '#fff' }}>
        <p>The current theme is {

me }) => (
      <div style={{ background: theme === 'light' ? '#fff' : '#333', color: theme === 'light' ? '#000' : '#fff' }}>
        <p>The current theme is {theme}</p>
        <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>Toggle Theme</button>
      </div>
    )}
  </ThemeContext.Consumer>
);

export default ThemedComponent;

When to Use Context
Context is useful for:
Global state that needs to be accessible in many parts of the application, such as user authentication status, application themes, or preferred language.
Avoiding prop drilling when you need to pass data through many levels of the component tree.
Performance Considerations
Rerenders: Context updates can cause all consumers to rerender, so it's important to avoid putting too much data or frequently changing data in context.
Optimization: Consider memoizing context values and using multiple context

