Step 2: Create a Page with SSR
Create a new file named pages/index.js. This file will define a page component that uses SSR.
// pages/index.js
import React from 'react';

// This function fetches data on the server side and passes it as props to the component
export async function getServerSideProps() {
  // Fetch data from an API or perform other server-side operations
  const res = await fetch('<https://api.example.com/data>');
  const data = await res.json();

  return {
    props: {
      data,
    },
  };
}

const Home = ({ data }) => {
  return (
    <div>
      <h1>Server Side Rendered Page</h1>
      <ul>
        {data.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>
    </div>
  );
};

export default Home;

