void main(String[] args) {
        String text = "  Hello Java!  ";

        // 1. Length of string
        System.out.println(text.length());        // Output: 15

        // 2. Trim whitespaces
        String trimmed = text.trim();
        System.out.println(trimmed);              // Output: "Hello Java!"

        // 3. Get character at index
        System.out.println(trimmed.charAt(0));    // Output: 'H'

        // 4. Substring extraction
        System.out.println(trimmed.substring(0, 5)); // Output: "Hello"

        // 5. Case conversion
        System.out.println(trimmed.toUpperCase()); // Output: "HELLO JAVA!"

        // 6. Verification
        System.out.println(trimmed.contains("Java")); // Output: true
    }
}

